  {"name":"Maize","local_name":"Makka / Jola / Mokkajonna","soil_types":["loamy","alluvial","sandy"],"ph_min":5.8,"ph_max":7.0,"temp_min":18,"temp_max":32,"rainfall_min":500,"rainfall_max":1000,"humidity_min":55,"humidity_max":75,"n_min":60,"n_max":100,"p_min":30,"p_max":60,"k_min":20,"k_max":50,"suitable_regions":["Karnataka","Andhra Pradesh","Maharashtra","Bihar","Rajasthan","Madhya Pradesh"],"crop_calendar":{"Kharif Sowing":"June-July","Rabi Sowing":"October-November","Harvesting":"90-100 days after sowing"},"cultivation_steps":"1. Deep ploughing and 2-3 harrowings\n2. Apply FYM 10 tonnes/ha as basal\n3. Treat seeds with fungicide + insecticide\n4. Sow at 60x25cm spacing\n5. Apply basal NPK at sowing\n6. Thin to 1 plant per hill at 15 days\n7. Top-dress urea at knee-high stage\n8. Weed control at 20 and 40 days\n9. Scout for Fall Army Worm from 30 days\n10. Harvest when husks turn brown and dry","water_needs":"Moderate — 500-800mm. Very sensitive to waterlogging. Critical at tasseling and grain filling.","disease_control":"Fall Army Worm: Emamectin benzoate 5SG 0.4g/L. Turcicum Blight: Mancozeb 2g/L. Use resistant hybrids."},
  {"name":"Cotton","local_name":"Kapas / Hatti / Patti","soil_types":["black","loamy"],"ph_min":6.0,"ph_max":8.0,"temp_min":24,"temp_max":35,"rainfall_min":600,"rainfall_max":1200,"humidity_min":55,"humidity_max":80,"n_min":90,"n_max":120,"p_min":35,"p_max":60,"k_min":35,"k_max":60,"suitable_regions":["Gujarat","Maharashtra","Telangana","Karnataka","Haryana","Punjab"],"crop_calendar":{"Sowing":"May-June","Squaring":"60-65 days","Picking":"October-January"},"cultivation_steps":"1. Deep summer ploughing to 30cm\n2. Apply FYM and basal NPK fertilizer\n3. Treat Bt cotton seeds with fungicide\n4. Sow at 60x90cm or 45x90cm spacing\n5. Thin at 15 days to 1 plant per hill\n6. Inter-cultivation at 30 and 60 days\n7. Apply fertilizer in 3 splits\n8. Install pheromone traps 5 per acre\n9. Scout for bollworms from 45 days\n10. Pick cotton every 10-15 days when open","water_needs":"Moderate — 600-1000mm. Drought tolerant once established. Critical at flowering and boll formation.","disease_control":"Bollworm: Emamectin 0.4g/L. Wilt: use resistant Bt varieties. Sucking pests: Imidacloprid 0.3ml/L."},
  {"name":"Banana","local_name":"Kela / Bale / Arati / Vazhai","soil_types":["alluvial","loamy"],"ph_min":5.5,"ph_max":7.0,"temp_min":24,"temp_max":35,"rainfall_min":1200,"rainfall_max":2000,"humidity_min":70,"humidity_max":90,"n_min":90,"n_max":120,"p_min":55,"p_max":80,"k_min":35,"k_max":60,"suitable_regions":["Karnataka","Tamil Nadu","Andhra Pradesh","Maharashtra","Kerala","Gujarat"],"crop_calendar":{"Planting":"June-July or Feb-March","Bunch Emergence":"9-10 months","Harvesting":"10-12 months after planting"},"cultivation_steps":"1. Dig pits 45x45x45cm\n2. Fill with topsoil + FYM + neem cake\n3. Plant disease-free tissue culture plants\n4. Install drip irrigation at 8-10L/plant/day\n5. Apply weekly fertigation with NPK\n6. Desuckering — keep only 1 follower per plant\n7. Spray micronutrients at bunch emergence\n8. Prop bunch with bamboo poles\n9. Cover bunch with perforated polybag\n10. Harvest when fingers fill out (75-80% maturity)","water_needs":"High — 1200-2000mm equivalent. Drip recommended at 8-10L per plant per day.","disease_control":"Panama Wilt: use resistant varieties like Grand Naine. Sigatoka: Propiconazole 0.1%. Moko: field sanitation."},
