  {"name":"Sugarcane","local_name":"Ganna / Kabbu / Cheruku / Karumbu","soil_types":["alluvial","loamy","black"],"ph_min":6.0,"ph_max":7.5,"temp_min":24,"temp_max":38,"rainfall_min":1000,"rainfall_max":2000,"humidity_min":60,"humidity_max":85,"n_min":80,"n_max":120,"p_min":40,"p_max":70,"k_min":40,"k_max":80,"suitable_regions":["Uttar Pradesh","Maharashtra","Karnataka","Tamil Nadu","Punjab","Andhra Pradesh"],"crop_calendar":{"Planting":"Feb-March or Oct-Nov","Earthing Up":"60 and 120 days after planting","Harvesting":"12-18 months after planting"},"cultivation_steps":"1. Deep ploughing 45cm and FYM application\n2. Select healthy disease-free setts with 2-3 buds\n3. Treat setts with Carbendazim 0.1% for 30 minutes\n4. Plant in furrows at 90cm row spacing\n5. Cover setts with 5cm soil\n6. First irrigation immediately after planting\n7. Earthing up at 60 and 120 days\n8. Apply NPK fertilizer in 4 splits\n9. Propping at 6-7 months to prevent lodging\n10. Harvest at Brix 18-20% using refractometer","water_needs":"High — 1500-2500mm. Critical at germination, tillering, grand growth, and maturity stages.","disease_control":"Red Rot: disease-free setts, Carbendazim treatment. Smut: hot water treatment. Top Borer: Trichogramma release."},
  {"name":"Chickpea","local_name":"Chana / Kadale / Senagalu / Kadalai","soil_types":["loamy","red","black"],"ph_min":6.0,"ph_max":8.0,"temp_min":15,"temp_max":25,"rainfall_min":300,"rainfall_max":600,"humidity_min":30,"humidity_max":60,"n_min":20,"n_max":50,"p_min":50,"p_max":80,"k_min":30,"k_max":60,"suitable_regions":["Madhya Pradesh","Rajasthan","Uttar Pradesh","Maharashtra","Andhra Pradesh","Karnataka"],"crop_calendar":{"Sowing":"October-November","Flowering":"50-60 days","Harvesting":"90-110 days after sowing"},"cultivation_steps":"1. Deep ploughing and 2 harrowings\n2. Seed treatment with Rhizobium + Thiram\n3. Sow at 30x10cm spacing at 60-75kg/ha\n4. Apply only phosphorus as basal — no nitrogen needed\n5. One pre-sowing irrigation if soil is dry\n6. Weed control at 30 and 45 days\n7. Monitor for pod borer from 45 days\n8. Harvest when leaves turn yellow and pods rattle","water_needs":"Low — 300-450mm. One critical irrigation at flowering + pod filling stage.","disease_control":"Pod Borer: Emamectin 0.4g/L. Wilt: Carbendazim 1g/L soil drench. Blight: Mancozeb 2g/L."},
  {"name":"Mango","local_name":"Aam / Mavina Hannu / Mamidi / Maanga","soil_types":["alluvial","red","loamy"],"ph_min":5.5,"ph_max":7.5,"temp_min":24,"temp_max":38,"rainfall_min":600,"rainfall_max":1200,"humidity_min":45,"humidity_max":70,"n_min":15,"n_max":40,"p_min":15,"p_max":40,"k_min":35,"k_max":60,"suitable_regions":["Andhra Pradesh","Uttar Pradesh","Karnataka","Bihar","Gujarat","Maharashtra"],"crop_calendar":{"Flowering":"November-January","Fruiting":"February-April","Harvesting":"April-July"},"cultivation_steps":"1. Dig pits 1x1x1m and fill with FYM + topsoil\n2. Plant grafted plants at 10x10m spacing\n3. Irrigate young trees weekly\n4. Apply NPK fertilizer annually after bearing\n5. Prune dead branches every year\n6. Mango hopper and weevil control from flowering\n7. Harvest when skin color changes and fruit separates easily","water_needs":"Moderate — 600-1000mm. Needs dry spell before flowering. Critical irrigation at fruit development.","disease_control":"Anthracnose: Carbendazim 1g/L at flowering. Powdery Mildew: Sulphur 2g/L. Hopper: Imidacloprid 0.5ml/L."},
  {"name":"Coconut","local_name":"Nariyal / Tenga / Kobbari / Tengai","soil_types":["sandy","alluvial","laterite"],"ph_min":5.0,"ph_max":7.0,"temp_min":24,"temp_max":35,"rainfall_min":1200,"rainfall_max":2500,"humidity_min":65,"humidity_max":90,"n_min":30,"n_max":60,"p_min":15,"p_max":40,"k_min":35,"k_max":60,"suitable_regions":["Kerala","Tamil Nadu","Karnataka","Andhra Pradesh","Goa","Maharashtra"],"crop_calendar":{"Planting":"June-July or September-October","First Harvest":"6-8 years after planting","Peak Bearing":"15-20 years"},"cultivation_steps":"1. Dig pits 1x1x1m filled with FYM and topsoil\n2. Select high-yielding hybrid seedlings (12 months old)\n3. Plant at 7.5x7.5m spacing for square system\n4. Basin irrigation at 200L per tree per week\n5. Apply NPK + micronutrients every 6 months\n6. Green manure crops between palms\n7. Rhinoceros beetle control with pheromone traps\n8. Harvest nuts every 45-60 days","water_needs":"High — 1200-2500mm. Cannot tolerate drought. Drip irrigation at 200L/tree/week in dry season.","disease_control":"Rhinoceros Beetle: pheromone traps + Metarhizium spray. Leaf Rot: Bordeaux paste. Bud Rot: Copper Oxychloride."},
  {"name":"Coffee","local_name":"Kapi / Coffee / Kofi","soil_types":["laterite","red","loamy"],"ph_min":5.5,"ph_max":6.5,"temp_min":18,"temp_max":28,"rainfall_min":1500,"rainfall_max":2500,"humidity_min":55,"humidity_max":80,"n_min":90,"n_max":120,"p_min":15,"p_max":40,"k_min":25,"k_max":50,"suitable_regions":["Karnataka","Kerala","Tamil Nadu","Andhra Pradesh"],"crop_calendar":{"Pruning":"January-February","Flowering":"March-April","Harvesting":"October-January"},"cultivation_steps":"1. Plant shade trees (Silver Oak) before coffee\n2. Dig pits 45x45x45cm\n3. Plant seedlings at 2.7x2.7m spacing for Arabica\n4. Mulch with dry leaves to conserve moisture\n5. Apply NPK fertilizer twice a year\n6. Pruning annually to maintain bush shape\n7. Borer control with Endosulfan or neem oil\n8. Harvest ripe red berries selectively (selective picking)","water_needs":"High — 1500-2500mm. Shade growing conserves moisture. Critical at flowering and berry development.","disease_control":"White Stem Borer: Endosulfan soil drench. Berry Borer: Beauveria bassiana spray. Leaf Rust: Copper hydroxide."},
  {"name":"Groundnut","local_name":"Moongphali / Kadalekai / Pallelu / Verkadalai","soil_types":["sandy","loamy","red"],"ph_min":5.5,"ph_max":7.0,"temp_min":20,"temp_max":35,"rainfall_min":500,"rainfall_max":1200,"humidity_min":50,"humidity_max":75,"n_min":20,"n_max":40,"p_min":40,"p_max":60,"k_min":20,"k_max":40,"suitable_regions":["Gujarat","Andhra Pradesh","Rajasthan","Tamil Nadu","Karnataka","Maharashtra"],"crop_calendar":{"Sowing":"June-July (Kharif) / January-February (Rabi)","Pegging":"40-50 days","Harvesting":"100-120 days"},"cultivation_steps":"1. Plough and harrow to fine tilth\n2. Apply gypsum 500kg/ha as basal\n3. Seed treatment with Rhizobium + Thiram\n4. Sow at 30x10cm spacing\n5. Weeding at 25 and 45 days\n6. Apply gypsum again at pegging stage\n7. Maintain optimum moisture at pegging\n8. Harvest when leaves yellow and inner shell shows dark markings\n9. Dry pods in sun for 3-4 days","water_needs":"Moderate — 500-700mm. Critical at flowering and pegging. Avoid waterlogging.","disease_control":"Leaf Spot: Mancozeb 2g/L at 30, 45, 60 days. Rust: same. Tikka: Chlorothalonil 2g/L."},
  {"name":"Soybean","local_name":"Soya / Soyabean","soil_types":["loamy","black","alluvial"],"ph_min":6.0,"ph_max":7.5,"temp_min":20,"temp_max":32,"rainfall_min":600,"rainfall_max":1000,"humidity_min":55,"humidity_max":80,"n_min":25,"n_max":50,"p_min":40,"p_max":70,"k_min":30,"k_max":50,"suitable_regions":["Madhya Pradesh","Maharashtra","Rajasthan","Karnataka","Andhra Pradesh"],"crop_calendar":{"Sowing":"June-July","Podding":"60-70 days","Harvesting":"90-100 days"},"cultivation_steps":"1. Plough and add FYM before sowing\n2. Seed treatment with Rhizobium + Thiram\n3. Sow at 45x5cm spacing at 70-80kg/ha\n4. Apply only phosphorus and potassium as basal\n5. Weeding at 20 and 40 days\n6. Monitor for semilooper and girdle beetle\n7. Harvest when 95% pods are brown","water_needs":"Moderate — 600-900mm. Critical at flowering and pod filling. Avoid standing water.","disease_control":"Yellow Mosaic: Imidacloprid for whitefly vector. Pod Borer: Quinalphos 1.5ml/L. Rust: Propiconazole 1ml/L."},
  {"name":"Jute","local_name":"Pat / Nalita / Juttu","soil_types":["alluvial","loamy"],"ph_min":6.0,"ph_max":7.5,"temp_min":24,"temp_max":38,"rainfall_min":1200,"rainfall_max":2500,"humidity_min":65,"humidity_max":90,"n_min":50,"n_max":80,"p_min":35,"p_max":60,"k_min":35,"k_max":60,"suitable_regions":["West Bengal","Bihar","Odisha","Assam","Uttar Pradesh"],"crop_calendar":{"Sowing":"March-May","Weeding":"25-30 days","Retting":"100-120 days"},"cultivation_steps":"1. Plough and harrow twice\n2. Sow at 25-30 cm row spacing\n3. Thin seedlings at 10-15 days\n4. Apply NPK fertilizer at sowing\n5. Weed control at 25 days\n6. Cut at 50% flowering stage for quality fibre\n7. Ret in slow-running water for 15-20 days\n8. Strip fibre and dry in sun","water_needs":"High — 1200-2500mm. Requires abundant moisture throughout growth. Alluvial floodplain soils ideal.","disease_control":"Stem Rot: Carbendazim 1g/L. Leaf Spot: Mancozeb 2g/L. Semilooper: Malathion 1ml/L."},
  {"name":"Lentil","local_name":"Masoor / Masure / Misur / Masuri","soil_types":["loamy","alluvial","sandy"],"ph_min":6.0,"ph_max":8.0,"temp_min":12,"temp_max":25,"rainfall_min":300,"rainfall_max":600,"humidity_min":35,"humidity_max":60,"n_min":10,"n_max":30,"p_min":55,"p_max":80,"k_min":15,"k_max":40,"suitable_regions":["Uttar Pradesh","Madhya Pradesh","Bihar","West Bengal","Rajasthan"],"crop_calendar":{"Sowing":"October-November","Flowering":"60-70 days","Harvesting":"100-110 days"},"cultivation_steps":"1. Plough to fine tilth\n2. Treat seeds with Rhizobium\n3. Sow at 30x10cm spacing at 35-40kg/ha\n4. Apply phosphorus as basal — no nitrogen\n5. Weed once at 30 days\n6. Protect from frost in December-January\n7. Harvest when lower pods turn yellow","water_needs":"Low — 300-450mm. One irrigation at flowering if soil is dry. Drought tolerant.","disease_control":"Rust: Mancozeb 2g/L. Blight: Zineb 2g/L. Pod Borer: Quinalphos 1.5ml/L."},
  {"name":"Mungbean","local_name":"Moong / Hesarukalu / Pesalu / Payiru","soil_types":["loamy","sandy","alluvial"],"ph_min":6.0,"ph_max":7.5,"temp_min":24,"temp_max":35,"rainfall_min":500,"rainfall_max":900,"humidity_min":55,"humidity_max":80,"n_min":15,"n_max":40,"p_min":35,"p_max":60,"k_min":15,"k_max":40,"suitable_regions":["Rajasthan","Maharashtra","Andhra Pradesh","Karnataka","Uttar Pradesh"],"crop_calendar":{"Sowing":"June-July or February-March","Flowering":"35-40 days","Harvesting":"60-70 days"},"cultivation_steps":"1. One ploughing and two harrowings\n2. Seed treatment with Rhizobium + Thiram\n3. Sow at 30x10cm at 15-20kg/ha\n4. Apply phosphorus and potassium as basal\n5. Weed at 20-25 days\n6. Harvest pods as they mature (2-3 pickings)\n7. Dry and thresh","water_needs":"Moderate — 500-700mm. Drought tolerant. One irrigation at flowering if dry.","disease_control":"Yellow Mosaic: Imidacloprid for whitefly. Cercospora Leaf Spot: Mancozeb 2g/L. Pod Borer: Quinalphos."},
  {"name":"Blackgram","local_name":"Urad / Uddina / Minumulu / Ulundu","soil_types":["loamy","alluvial","black"],"ph_min":5.5,"ph_max":7.5,"temp_min":24,"temp_max":35,"rainfall_min":600,"rainfall_max":1000,"humidity_min":55,"humidity_max":80,"n_min":30,"n_max":60,"p_min":50,"p_max":80,"k_min":15,"k_max":40,"suitable_regions":["Andhra Pradesh","Tamil Nadu","Uttar Pradesh","Maharashtra","Karnataka"],"crop_calendar":{"Sowing":"June-July","Flowering":"45-50 days","Harvesting":"70-80 days"},"cultivation_steps":"1. Plough twice and harrow\n2. Rhizobium + Thiram seed treatment\n3. Sow at 30x10cm at 15-20kg/ha\n4. Apply phosphorus as basal\n5. Weed at 20-25 days\n6. Harvest when 80% pods are black/mature\n7. Sun dry and thresh","water_needs":"Moderate — 600-800mm. Sensitive to waterlogging. One protective irrigation at flowering.","disease_control":"Yellow Mosaic Virus: Monocrotophos. Cercospora Leaf Spot: Mancozeb 2g/L. Pod Borer: Chlorpyriphos."},
  {"name":"Papaya","local_name":"Papita / Parangi / Boppayi / Pappali","soil_types":["alluvial","loamy","red"],"ph_min":5.5,"ph_max":7.0,"temp_min":24,"temp_max":38,"rainfall_min":1000,"rainfall_max":2000,"humidity_min":65,"humidity_max":85,"n_min":40,"n_max":70,"p_min":40,"p_max":70,"k_min":40,"k_max":70,"suitable_regions":["Karnataka","Andhra Pradesh","Tamil Nadu","Maharashtra","Gujarat","Bihar"],"crop_calendar":{"Planting":"February-March or September-October","Flowering":"5-7 months","Harvesting":"9-11 months after planting"},"cultivation_steps":"1. Dig pits 50x50x50cm with FYM\n2. Plant 3 seedlings per pit initially\n3. Remove extra plants keeping best one\n4. Drip or basin irrigation twice weekly\n5. Apply NPK monthly\n6. Remove male plants (keep 10% for pollination)\n7. Support heavy bearing stems\n8. Harvest when skin turns yellowish","water_needs":"Moderate-High — 1000-1500mm. Drip irrigation preferred. Cannot tolerate waterlogging.","disease_control":"Papaya Ring Spot Virus: use virus-free seedlings, control aphids. Anthracnose: Mancozeb 2g/L. Powdery Mildew: Sulphur."},
