class Command(BaseCommand):
    help = 'Seed all data — crops (23), market prices (59), schemes (10)'

    def handle(self, *args, **kwargs):
        self.stdout.write(self.style.HTTP_INFO('\n🌱 Seeding AGRO_ADV database...\n'))

        self.stdout.write('Seeding 23 crops...')
        created_crops = 0
        for c in CROPS:
            _, created = Crop.objects.get_or_create(name=c['name'], defaults=c)
            if created:
                created_crops += 1
        self.stdout.write(self.style.SUCCESS(f'  ✓ {Crop.objects.count()} crops total ({created_crops} new)'))

        self.stdout.write('Seeding market prices...')
        for crop, cat, state, district, market, mn, mx, modal, demand in MARKET:
            MarketPrice.objects.update_or_create(
                crop_name=crop, market=market, state=state,
                defaults={'category':cat,'district':district,'min_price':mn,'max_price':mx,'modal_price':modal,'demand':demand}
            )
        self.stdout.write(self.style.SUCCESS(f'  ✓ {MarketPrice.objects.count()} market price records'))

        self.stdout.write('Seeding government schemes...')
        for s in SCHEMES:
            Scheme.objects.get_or_create(title=s['title'], defaults=s)
        self.stdout.write(self.style.SUCCESS(f'  ✓ {Scheme.objects.count()} schemes'))

        self.stdout.write(self.style.SUCCESS('\n✅ Seeding complete!\n'))
        self.stdout.write('Run: python manage.py runserver\n')
        self.stdout.write('Open: http://127.0.0.1:8000\n')
